HIDDEN_S1 = 'import copy\nimport json\n\nEXAMPLES = json.loads(\'{"project.gueltig": {"schema_version": "1.0.0", "kind": "factory.project", "backing": {"store": "project_registry", "project_id": "PRJ-3f9a1c2b7d4e", "workspace_path": "projects/PRJ-3f9a1c2b7d4e", "qualification": "MANAGED_WORKSPACE_NOT_VM", "created_at": "2026-11-06T11:40:12.345678+00:00"}, "display_name": "Beispiel Software Factory", "status": "ACTIVE"}, "workflow.gueltig": {"schema_version": "1.0.0", "kind": "factory.workflow", "workflow_id": "WF-55cf1725549ddc93e4855595", "revision": 2, "digest": "068f057d54567dadeb470598e469e7f6064d9e3ef69ccfd4c756f492098d8ad3", "record_digest": "8e4284462977901081a032495c0de1253dcd7fde585c6eeeaf82292ea4a382a5", "previous_revision": 1, "name": "Anfrage prüfen", "change_note": "IF-Bedingung ergänzt", "process_model": false, "execution": {"executable": true, "profile": "n8n-local-data-v1", "reason": null}}, "project.ungueltig": {"schema_version": "1.0.0", "kind": "factory.project", "backing": {"store": "project_registry", "project_id": "PRJ-3f9a1c2b7d4e", "workspace_path": "projects/PRJ-3f9a1c2b7d4e", "qualification": "MANAGED_WORKSPACE_NOT_VM", "created_at": "2026-11-06T11:40:12.345678+00:00"}, "display_name": "Beispiel Software Factory", "status": "ARCHIVED"}, "workflow.ungueltig": {"schema_version": "1.0.0", "kind": "factory.workflow", "workflow_id": "WF-55cf1725549ddc93e4855595", "revision": 2, "digest": "068f057d54567dadeb470598e469e7f6064d9e3ef69ccfd4c756f492098d8ad3", "record_digest": "8e4284462977901081a032495c0de1253dcd7fde585c6eeeaf82292ea4a382a5", "previous_revision": 1, "name": "Anfrage prüfen", "change_note": "IF-Bedingung ergänzt", "process_model": true, "execution": {"executable": true, "profile": "n8n-local-data-v1", "reason": null}}}\')\nNEGATIVE = [(\'project.gueltig\', [(\'set\', [\'status\'], \'PAUSED\')]), (\'project.gueltig\', [(\'set\', [\'display_name\'], \'\')]), (\'project.gueltig\', [(\'set\', [\'extra\'], 1)]), (\'project.gueltig\', [(\'del\', [\'backing\'])]), (\'project.gueltig\', [(\'set\', [\'backing\', \'qualification\'], \'VM\')]), (\'workflow.gueltig\', [(\'set\', [\'revision\'], 0)]), (\'workflow.gueltig\', [(\'set\', [\'process_model\'], True), (\'set\', [\'execution\', \'executable\'], True), (\'set\', [\'execution\', \'reason\'], None)]), (\'workflow.gueltig\', [(\'set\', [\'execution\', \'executable\'], False), (\'set\', [\'execution\', \'reason\'], None)]), (\'workflow.gueltig\', [(\'set\', [\'digest\'], \'ABC\')]), (\'workflow.gueltig\', [(\'set\', [\'execution\', \'profile\'], \'anderes-profil\')])]\nfrom factory_sdk import pruefe_project, pruefe_workflow, FabrikFehler\n\nFUNKTIONEN = {\'project\': pruefe_project, \'workflow\': pruefe_workflow, \'project\': pruefe_project, \'workflow\': pruefe_workflow}\n\ndef anwenden(obj, ops):\n    for op in ops:\n        pfad = op[1]\n        ziel = obj\n        for schluessel in pfad[:-1]:\n            ziel = ziel[schluessel]\n        if op[0] == \'set\':\n            ziel[pfad[-1]] = copy.deepcopy(op[2])\n        elif isinstance(ziel, dict):\n            ziel.pop(pfad[-1], None)\n    return obj\n\nfor name, fn in FUNKTIONEN.items():\n    base = EXAMPLES[name + \'.gueltig\'] if name + \'.gueltig\' in EXAMPLES else None\n    if base is not None:\n        fn(copy.deepcopy(base))\n\nfor name in [\'project\', \'workflow\']:\n    try:\n        FUNKTIONEN[name](copy.deepcopy(EXAMPLES[name + \'.ungueltig\']))\n    except FabrikFehler as exc:\n        assert exc.code and isinstance(exc.field, str), name\n    else:\n        raise AssertionError(name + \' ungueltig wurde angenommen\')\n\nfor fall, ops in NEGATIVE:\n    objekt = fall.split(\'.\')[0]\n    obj = anwenden(copy.deepcopy(EXAMPLES[fall.split(\'.\')[0] + \'.gueltig\']), ops)\n    try:\n        FUNKTIONEN[objekt](obj)\n    except FabrikFehler as exc:\n        assert exc.code and isinstance(exc.field, str), (fall, ops)\n    else:\n        raise AssertionError(f\'Negativfall angenommen: {fall} {ops}\')\n\nprint(\'ok S1\')\n'

